def median(self, window_size: int) -> float:
    """
    Return the median of the latest `window_size` values in the buffer.
    """
    if not self._data:
        return 0.0
    window_size = min(window_size, len(self._data))
    return np.median([x[0] for x in self._data[-window_size:]])
